def parse_number_at(text, start):
    index = start
    while index < len(text) and not (text[index].isdigit() or text[index] == "-"):
        index += 1
    end = index
    if end < len(text) and text[end] == "-":
        end += 1
    while end < len(text) and (text[end].isdigit() or text[end] in ",."):
        end += 1
    raw = text[index:end].strip().rstrip(".,")
    if not raw or raw == "-":
        return None
    if "," in raw and "." not in raw and len(raw.rsplit(",", 1)[1]) == 2:
        normalized = raw.replace(",", ".")
    else:
        normalized = raw.replace(",", "")
    return float(normalized)

def amount_after_label(text, label):
    lowered = text.lower()
    values = []
    search_from = 0
    while True:
        position = lowered.find(label, search_from)
        if position < 0:
            break
        before_ok = position == 0 or not lowered[position - 1].isalnum()
        after_position = position + len(label)
        after_ok = after_position == len(lowered) or not lowered[after_position].isalnum()
        if before_ok and after_ok:
            segment_end = min(len(text), after_position + 100)
            segment = text[after_position:segment_end]
            dollar_position = segment.find("$")
            usd_position = segment.lower().find("usd")
            if dollar_position >= 0:
                value = parse_number_at(segment, dollar_position + 1)
            elif usd_position >= 0:
                value = parse_number_at(segment, usd_position + 3)
            else:
                value = parse_number_at(segment, 0)
            if value is not None:
                values.append(value)
        search_from = position + len(label)
    return values

def extract_bill_amount(content):
    text = str(content)
    for label in ("total amount due", "amount due", "grand total", "total due", "bill total", "total cost", "amount charged", "payment amount", "total", "amount", "cost"):
        labeled_values = amount_after_label(text, label)
        if labeled_values:
            return labeled_values[-1]
    currency_values = []
    search_from = 0
    while True:
        currency_position = text.find("$", search_from)
        if currency_position < 0:
            break
        value = parse_number_at(text, currency_position + 1)
        if value is not None:
            currency_values.append(value)
        search_from = currency_position + 1
    unique_currency_values = []
    for value in currency_values:
        if value not in unique_currency_values:
            unique_currency_values.append(value)
    if len(unique_currency_values) != 1:
        raise ValueError("A bill does not contain one unambiguous payable amount")
    return unique_currency_values[0]

